use freedom_consensus::{validate_genesis,ConsensusConfig}; use freedom_crypto::verify; use freedom_primitives::{CHAIN_ID,Hash}; use freedom_state::{ChainState,StateError}; use freedom_types::{Genesis,Receipt,Transaction,TxKind,ClaimRewardPayload,PurchasePayload,BillingPayload};
pub fn initialize(g:&Genesis)->Result<ChainState,String>{if g.chain_id!=CHAIN_ID{return Err("invalid chain id".into())}let s=ChainState::genesis(g);validate_genesis(&s,&ConsensusConfig::default())?;s.assert_invariants();Ok(s)}
pub fn execute_transaction(s:&mut ChainState,tx:&Transaction)->Result<Receipt,String>{if tx.chain_id!=CHAIN_ID{return Err("invalid chain id".into())}let a=s.accounts.get(&tx.sender).ok_or_else(||"sender account not found".to_string())?;if tx.signature.len()!=64{return Err("invalid signature length".into())}let mut sig=[0u8;64];sig.copy_from_slice(&tx.signature);if !verify(&a.public_key,&tx.signing_bytes(),&sig){return Err("invalid transaction signature".into())}let h:Hash=tx.hash();let before=s.events.len();s.execute_transaction(tx).map_err(format_state_error)?;s.assert_invariants();let events=s.events[before..].to_vec();Ok(Receipt{tx_hash:h,success:true,gas_used:1,events})}
fn format_state_error(e:StateError)->String{format!("{e:?}")}
#[cfg(test)]mod tests{use super::*;use freedom_crypto::{generate_keypair,sign};use freedom_primitives::{address_from_public_key,hash_bytes};use freedom_state::Account;use freedom_types::{RegisterNodePayload,SubmitContributionPayload,CreateTicketPayload,DrawConfig,DrawType};
fn tx(k:&ed25519_dalek::SigningKey,s:[u8;32],n:u64,kind:TxKind,p:Vec<u8>)->Transaction{let mut t=Transaction{chain_id:CHAIN_ID,sender:s,nonce:n,kind,payload:p,fee:0,signature:vec![]};t.signature=sign(k,&t.signing_bytes()).to_vec();t}
#[test]fn verified_work_mints_once(){let k=generate_keypair();let pk=k.verifying_key().to_bytes();let owner=address_from_public_key(&pk);let vk=generate_keypair();let vpk=vk.verifying_key().to_bytes();let vid=hash_bytes(&vpk);let mut s=ChainState::genesis(&Genesis{chain_id:CHAIN_ID,initial_supply:0,validators:vec![freedom_types::Validator{validator_id:vid,owner,consensus_key:vpk,stake:0,blocks_proposed:0,blocks_finalized:0,missed_votes:0}]});s.insert_account(Account::new(pk,0));let nid=hash_bytes(b"node");execute_transaction(&mut s,&tx(&k,owner,0,TxKind::RegisterNode,RegisterNodePayload{node_id:nid,capabilities:1}.encode())).unwrap();let cid=hash_bytes(b"contribution");execute_transaction(&mut s,&tx(&k,owner,1,TxKind::SubmitContribution,SubmitContributionPayload{contribution_id:cid,node_id:nid,task_id:hash_bytes(b"task"),work_units:100,quality_score:10000,result_hash:hash_bytes(b"result")}.encode())).unwrap();s.verify_contribution(cid,vec![vid],10000).unwrap();let before=s.supply.total;s.claim_reward(cid).unwrap();assert_eq!(s.supply.total,before+100);assert_eq!(s.accounts.get(&owner).unwrap().balance,100);assert_eq!(s.contributions.get(&cid).unwrap().status,freedom_state::ContributionStatus::Rewarded);assert!(s.claim_reward(cid).is_err());assert_eq!(s.supply.total,before+100);}

#[test]fn paid_ai_bot_purchase_moves_fdm_without_minting(){let k=generate_keypair();let pk=k.verifying_key().to_bytes();let buyer=address_from_public_key(&pk);let merchant=hash_bytes(b"cu-ai-billing");let mut s=ChainState::genesis(&Genesis{chain_id:CHAIN_ID,initial_supply:0,validators:vec![]});s.insert_account(Account::new(pk,100));s.supply.total=100;s.supply.circulating=100;let reference=hash_bytes(b"chat-bot-connection");let payload=PurchasePayload{product_id:1,merchant,price:10,reference}.encode();execute_transaction(&mut s,&tx(&k,buyer,0,TxKind::Purchase,payload)).unwrap();assert_eq!(s.accounts.get(&buyer).unwrap().balance,90);assert_eq!(s.accounts.get(&merchant).unwrap().balance,10);assert_eq!(s.supply.total,100);assert_eq!(s.supply.circulating,100);assert_eq!(s.purchases.len(),1);assert!(execute_transaction(&mut s,&tx(&k,buyer,1,TxKind::Purchase,PurchasePayload{product_id:1,merchant,price:10,reference}.encode())).is_err());}
#[test]fn billing_reserve_capture_refund(){let k=generate_keypair();let pk=k.verifying_key().to_bytes();let buyer=address_from_public_key(&pk);let merchant=hash_bytes(b"merchant");let mut s=ChainState::genesis(&Genesis{chain_id:CHAIN_ID,initial_supply:0,validators:vec![]});s.insert_account(Account::new(pk,10000));s.supply.total=10000;s.supply.circulating=10000;let bid=hash_bytes(b"billing");let payload=BillingPayload{billing_id:bid,product_id:1,merchant,amount:10000,reference:hash_bytes(b"ref")}.encode();execute_transaction(&mut s,&tx(&k,buyer,0,TxKind::Purchase,payload)).unwrap();s.reserve_billing(&tx(&k,buyer,1,TxKind::Purchase,BillingPayload{billing_id:hash_bytes(b"billing2"),product_id:1,merchant,amount:10000,reference:hash_bytes(b"ref2")}.encode())).unwrap_err();let id=hash_bytes(b"billing3");s.reserve_billing(&tx(&k,buyer,1,TxKind::Purchase,BillingPayload{billing_id:id,product_id:1,merchant,amount:10000,reference:hash_bytes(b"ref3")}.encode())).unwrap();assert_eq!(s.accounts.get(&buyer).unwrap().balance,0);assert_eq!(s.accounts.get(&buyer).unwrap().locked,10000);s.refund_billing(id).unwrap();assert_eq!(s.accounts.get(&buyer).unwrap().balance,10000);assert_eq!(s.accounts.get(&buyer).unwrap().locked,0);}
#[test]fn tickets_use_fdm_and_draw_payout(){let k=generate_keypair();let pk=k.verifying_key().to_bytes();let owner=address_from_public_key(&pk);let mut s=ChainState::genesis(&Genesis{chain_id:CHAIN_ID,initial_supply:0,validators:vec![]});s.insert_account(Account::new(pk,100_000));s.supply.total=100_000;s.supply.circulating=100_000;let draw_id=hash_bytes(b"daily-draw");s.create_draw(DrawConfig{draw_id,draw_type:DrawType::Daily,ticket_price_mfdm:10_000,winner_count:2,starts_at:0,ends_at:0,seed_block:7}).unwrap();let tx=tx(&k,owner,0,TxKind::CreateTicket,CreateTicketPayload{draw_id,quantity:10}.encode());execute_transaction(&mut s,&tx).unwrap();assert_eq!(s.accounts.get(&owner).unwrap().balance,0);assert_eq!(s.draws.get(&draw_id).unwrap().total_tickets,10);assert_eq!(s.draws.get(&draw_id).unwrap().prize_pool_mfdm,60_000);assert_eq!(s.draws.get(&draw_id).unwrap().cu_fund_mfdm,30_000);assert_eq!(s.draws.get(&draw_id).unwrap().annual_reserve_mfdm,10_000);assert_eq!(s.events.len(),11);let result=s.execute_draw(draw_id).unwrap();assert_eq!(result.winners.len(),2);assert_eq!(result.prize_pool_mfdm,60_000);assert_eq!(s.supply.total,100_000);assert_eq!(s.supply.treasury,40_000);assert!(s.execute_draw(draw_id).is_err());}
}
